CREATE DATABASE IF NOT EXISTS grafica CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE grafica;
CREATE TABLE IF NOT EXISTS funcionarios (id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,senha VARCHAR(255) NOT NULL,cargo ENUM('administrador','gerente','atendente','producao','estoquista') NOT NULL,ativo TINYINT(1) NOT NULL DEFAULT 1,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clientes(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(190),telefone VARCHAR(30),criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS produtos(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(150) NOT NULL,tipo ENUM('produto','servico') NOT NULL DEFAULT 'produto',preco DECIMAL(10,2) NOT NULL DEFAULT 0,estoque INT NOT NULL DEFAULT 0,minimo INT NOT NULL DEFAULT 0,ativo TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pedidos(id INT AUTO_INCREMENT PRIMARY KEY,cliente_id INT NOT NULL,funcionario_id INT NOT NULL,status ENUM('recebido','producao','pronto','entregue','cancelado') NOT NULL DEFAULT 'recebido',total DECIMAL(10,2) NOT NULL DEFAULT 0,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(funcionario_id) REFERENCES funcionarios(id));
CREATE TABLE IF NOT EXISTS pedido_itens(id INT AUTO_INCREMENT PRIMARY KEY,pedido_id INT NOT NULL,produto_id INT NOT NULL,quantidade INT NOT NULL,preco_unitario DECIMAL(10,2) NOT NULL,FOREIGN KEY(pedido_id) REFERENCES pedidos(id),FOREIGN KEY(produto_id) REFERENCES produtos(id));
CREATE TABLE IF NOT EXISTS movimentacoes(id INT AUTO_INCREMENT PRIMARY KEY,produto_id INT NOT NULL,funcionario_id INT NOT NULL,tipo ENUM('entrada','saida') NOT NULL,quantidade INT NOT NULL,observacao VARCHAR(255),criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(produto_id) REFERENCES produtos(id),FOREIGN KEY(funcionario_id) REFERENCES funcionarios(id));
CREATE TABLE IF NOT EXISTS pagamentos(id INT AUTO_INCREMENT PRIMARY KEY,pedido_id INT NOT NULL,valor DECIMAL(10,2) NOT NULL,forma VARCHAR(40) NOT NULL,pago_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(pedido_id) REFERENCES pedidos(id));
CREATE TABLE IF NOT EXISTS relatorios(id INT AUTO_INCREMENT PRIMARY KEY,gerente_id INT NOT NULL,inicio DATE NOT NULL,fim DATE NOT NULL,destinatario VARCHAR(190),enviado_em DATETIME NULL,criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(gerente_id) REFERENCES funcionarios(id));
